#!/usr/bin/env node
/**
 * LabEx library quality gate.
 *
 * lib/labex is generated by scripts/import-labex.cjs from the locally cloned
 * LabEx open-source corpus. Because it is generated, the usual curriculum gate
 * never sees it — this check locks in the same standards for the 1,700+ labs:
 *
 *   - every generated lesson passes validateBank (solvable chains, unique
 *     option banks, teaching notes on every answer);
 *   - every lesson keeps its attribution line and at least three questions;
 *   - prompts are unique inside a lesson and options stay readable;
 *   - the eager metadata registry and the lazy category banks agree exactly;
 *   - nothing from the LabEx VM leaks into learner-facing copy.
 *
 * Runs inside `npm test`.
 */
'use strict';

const fs = require('node:fs');
const path = require('node:path');
const ts = require('typescript');

const ROOT = path.join(__dirname, '..');
const LESSONS = path.join(ROOT, 'lib', 'labex', 'lessons');

require.extensions['.ts'] = (module, filename) => {
  const source = fs.readFileSync(filename, 'utf8');
  const { outputText } = ts.transpileModule(source, {
    compilerOptions: {
      module: ts.ModuleKind.CommonJS,
      target: ts.ScriptTarget.ES2020,
      esModuleInterop: true,
    },
    fileName: filename,
  });
  module._compile(outputText, filename);
};

const { validateBank, normalizeAnswer } = require(path.join(ROOT, 'lib', 'quizBank.ts'));
const { LABEX_CATEGORIES, LABEX_META, LABEX_COUNT } = require(path.join(ROOT, 'lib', 'labex', 'index.ts'));

const failures = [];
const fail = (message) => failures.push(message);

const VM_COPY = /\b(go live|web 8080|vm startup|virtual machine|jupyter notebook)\b/i;
const MAX_OPTION = 95;

/* ---- metadata registry ---- */
if (LABEX_COUNT !== Object.keys(LABEX_META).length) fail('LABEX_COUNT disagrees with the registry.');
if (LABEX_COUNT < 1500) fail(`The lab library looks truncated: only ${LABEX_COUNT} labs.`);

const categoryIds = LABEX_CATEGORIES.map((c) => c.id);
if (new Set(categoryIds).size !== categoryIds.length) fail('duplicate LabEx category id.');
for (const category of LABEX_CATEGORIES) {
  if (!category.title?.trim() || !category.blurb?.trim()) fail(`${category.id}: missing title/blurb.`);
  if (!(category.count > 0)) fail(`${category.id}: empty category.`);
  if (!Array.isArray(category.sources) || category.sources.length === 0) {
    fail(`${category.id}: no attributed source repositories.`);
  }
}

/* ---- lesson banks ---- */
const seenIds = new Set();
const metaSeen = new Set();
const counts = {};
let lessons = 0;
let questions = 0;

for (const file of fs.readdirSync(LESSONS).filter((f) => f.endsWith('.ts'))) {
  const category = path.basename(file, '.ts');
  const module = require(path.join(LESSONS, file));
  const banks = Object.values(module).filter((value) => value && typeof value === 'object');
  if (banks.length !== 1) {
    fail(`${file}: expected exactly one exported bank.`);
    continue;
  }
  const bank = banks[0];
  for (const [key, lesson] of Object.entries(bank)) {
    lessons += 1;
    counts[category] = (counts[category] || 0) + 1;
    if (seenIds.has(key)) fail(`${key}: duplicate lesson id.`);
    seenIds.add(key);
    if (lesson.id !== key) fail(`${key}: id field is ${lesson.id}.`);
    if (!key.startsWith('labex-')) fail(`${key}: id must start with labex-.`);
    if (!lesson.title?.trim()) fail(`${key}: empty title.`);

    const meta = LABEX_META[key];
    if (!meta) {
      fail(`${key}: missing from LABEX_META (the library screen could not open it).`);
    } else {
      metaSeen.add(key);
      if (meta.title !== lesson.title) fail(`${key}: registry title differs from the bank.`);
      if (meta.category !== category) fail(`${key}: registry category ${meta.category} != ${category}.`);
      if (!(meta.minutes > 0)) fail(`${key}: minutes must be positive.`);
    }

    try {
      validateBank(lesson);
    } catch (error) {
      fail(`${key}: ${error.message}`);
      continue;
    }

    const theory = lesson.theory.join(' ').trim();
    if (theory.length < 40) fail(`${key}: theory is too thin.`);
    if (!/Source:\s/.test(theory)) fail(`${key}: missing source attribution.`);
    if (VM_COPY.test(theory)) fail(`${key}: LabEx VM copy leaked into the theory.`);
    if (lesson.questions.length < 3) fail(`${key}: needs at least 3 questions.`);
    questions += lesson.questions.length;

    const prompts = new Set();
    for (const question of lesson.questions) {
      const prompt = question.prompt.trim().toLowerCase();
      if (prompts.has(prompt)) fail(`${key}: duplicate prompt.`);
      prompts.add(prompt);
      if (VM_COPY.test(question.prompt) || VM_COPY.test(question.explain)) {
        fail(`${key}: LabEx VM copy leaked into a question.`);
      }
      if (question.kind === 'code') {
        const code = question.code;
        if (!code || !['js', 'html', 'css'].includes(code.language)) {
          fail(`${key}: code question needs a js/html/css exercise.`);
        } else {
          if (typeof code.starter !== 'string' || !code.starter.trim()) fail(`${key}: code starter is empty.`);
          if (!Array.isArray(code.tests) || code.tests.length < 2) {
            fail(`${key}: code exercise needs at least two tests.`);
          }
          if (code.language === 'js' && !question.correctChain[0]?.trim()) {
            fail(`${key}: js exercise needs a reference solution.`);
          }
        }
        continue;
      }
      if (question.scrambledTokens.length < 2) {
        fail(`${key}: question has fewer than two options.`);
        continue;
      }
      if (new Set(question.scrambledTokens.map(normalizeAnswer)).size !== question.scrambledTokens.length) {
        fail(`${key}: duplicate option.`);
      }
      const long = question.scrambledTokens.find((option) => option.length > MAX_OPTION);
      if (long) fail(`${key}: option too long (${long.length} chars).`);
      if (
        question.correctChain.length === 1 &&
        !question.scrambledTokens.some(
          (option) => normalizeAnswer(option) === normalizeAnswer(question.correctChain[0])
        )
      ) {
        fail(`${key}: answer missing from its option bank.`);
      }
    }
  }
}

for (const id of Object.keys(LABEX_META)) {
  if (!metaSeen.has(id)) fail(`${id}: registry entry has no lesson bank.`);
}

for (const category of LABEX_CATEGORIES) {
  if ((counts[category.id] || 0) !== category.count) {
    fail(`${category.id}: registry says ${category.count} labs, bank has ${counts[category.id] || 0}.`);
  }
}

if (failures.length > 0) {
  console.error('LabEx library check failed:');
  for (const failure of failures) console.error(`  ✗ ${failure}`);
  process.exit(1);
}

console.log(
  `LabEx library OK — ${lessons} labs, ${questions} questions, ${LABEX_CATEGORIES.length} categories.`
);
